{"content":"import numpy as np
A = ['np.inf', '33.33', '33.33', '33.37']
NA = np.asarray(A)
# BEGIN SOLUTION
# Convert string 'np.inf' to actual np.inf and numeric strings to float
# Use np.vectorize with a function that evaluates 'np.inf' as np.inf
def convert_str(x):
    if x == 'np.inf':
        return np.inf
    else:
        return float(x)
vectorized_convert = np.vectorize(convert_str)
converted = vectorized_convert(NA)
AVG = np.mean(converted)
# END SOLUTION","path":"solution.py"}
